import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.D7EjqxMK.js";const b=JSON.parse('{"title":"Vibe vs Spec 对比分析","description":"","frontmatter":{},"headers":[],"relativePath":"07-ai-coding/04_vibe_vs_spec/01_对比分析.md","filePath":"07-ai-coding/04_vibe_vs_spec/01_对比分析.md"}'),i={name:"07-ai-coding/04_vibe_vs_spec/01_对比分析.md"};function n(o,t,s,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="vibe-vs-spec-对比分析" tabindex="-1">Vibe vs Spec 对比分析 <a class="header-anchor" href="#vibe-vs-spec-对比分析" aria-label="Permalink to &quot;Vibe vs Spec 对比分析&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块四 · 04_vibe_vs_spec · 第 1 节 <strong>难度</strong>：⭐⭐⭐</p></blockquote><hr><h2 id="_1-核心对比" tabindex="-1">1. 核心对比 <a class="header-anchor" href="#_1-核心对比" aria-label="Permalink to &quot;1. 核心对比&quot;">​</a></h2><h3 id="工作模式对比" tabindex="-1">工作模式对比 <a class="header-anchor" href="#工作模式对比" aria-label="Permalink to &quot;工作模式对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Vibe Coding</th><th>Spec-Driven Development</th></tr></thead><tbody><tr><td><strong>交互方式</strong></td><td>对话式（&quot;Make it bigger&quot;）</td><td>文档式（详细 PRD）</td></tr><tr><td><strong>开发速度</strong></td><td>极快（秒级反馈）</td><td>中等（需写 PRD）</td></tr><tr><td><strong>代码质量</strong></td><td>不可预测</td><td>可预测、可验证</td></tr><tr><td><strong>适用阶段</strong></td><td>创意探索、快速原型</td><td>生产开发、团队协作</td></tr><tr><td><strong>可维护性</strong></td><td>低（代码结构混乱）</td><td>高（按规格执行）</td></tr><tr><td><strong>团队协作</strong></td><td>困难（无规格文档）</td><td>容易（PRD 对齐）</td></tr><tr><td><strong>可追溯性</strong></td><td>低（对话历史不结构化）</td><td>高（需求→代码映射）</td></tr><tr><td><strong>学习曲线</strong></td><td>低（谁都会写 Prompt）</td><td>中（需学会写 PRD）</td></tr><tr><td><strong>成本</strong></td><td>低（工具免费）</td><td>中（需花时间写 PRD）</td></tr><tr><td><strong>适合人群</strong></td><td>初学者、独立开发者</td><td>团队、专业开发者</td></tr></tbody></table><h3 id="核心范式对比" tabindex="-1">核心范式对比 <a class="header-anchor" href="#核心范式对比" aria-label="Permalink to &quot;核心范式对比&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vibe Coding:</span></span>
<span class="line"><span>  用户意图 → 对话 → AI 理解意图 → 生成代码</span></span>
<span class="line"><span>  (模糊 → 调整 → 模糊)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Spec Coding:</span></span>
<span class="line"><span>  详细需求 → PRD → AI 执行 PRD → 生成代码</span></span>
<span class="line"><span>  (具体 → 执行 → 验证)</span></span></code></pre></div><hr><h2 id="_2-vibe-coding-的优缺点" tabindex="-1">2. Vibe Coding 的优缺点 <a class="header-anchor" href="#_2-vibe-coding-的优缺点" aria-label="Permalink to &quot;2. Vibe Coding 的优缺点&quot;">​</a></h2><h3 id="✅-优点" tabindex="-1">✅ 优点 <a class="header-anchor" href="#✅-优点" aria-label="Permalink to &quot;✅ 优点&quot;">​</a></h3><ul><li>极速原型（几分钟出可用版本）</li><li>低门槛（不需要深厚的编程知识）</li><li>创意自由（探索式设计空间大）</li><li>学习曲线低</li></ul><h3 id="❌-缺点" tabindex="-1">❌ 缺点 <a class="header-anchor" href="#❌-缺点" aria-label="Permalink to &quot;❌ 缺点&quot;">​</a></h3><ul><li>代码质量不可控</li><li>无架构规划</li><li>不适合团队协作</li><li>代码难以维护</li><li>缺乏安全保证</li></ul><hr><h2 id="_3-spec-coding-的优缺点" tabindex="-1">3. Spec Coding 的优缺点 <a class="header-anchor" href="#_3-spec-coding-的优缺点" aria-label="Permalink to &quot;3. Spec Coding 的优缺点&quot;">​</a></h2><h3 id="✅-优点-1" tabindex="-1">✅ 优点 <a class="header-anchor" href="#✅-优点-1" aria-label="Permalink to &quot;✅ 优点&quot;">​</a></h3><ul><li>代码质量可预测</li><li>可测试、可验证</li><li>团队协作友好（PRD 作为对齐工具）</li><li>代码结构清晰</li><li>生产就绪</li></ul><h3 id="❌-缺点-1" tabindex="-1">❌ 缺点 <a class="header-anchor" href="#❌-缺点-1" aria-label="Permalink to &quot;❌ 缺点&quot;">​</a></h3><ul><li>写 PRD 需要时间</li><li>灵活性较低</li><li>学习曲线较陡</li><li>过度规格可能导致僵化</li></ul><hr><h2 id="_4-典型场景对比" tabindex="-1">4. 典型场景对比 <a class="header-anchor" href="#_4-典型场景对比" aria-label="Permalink to &quot;4. 典型场景对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>Vibe Coding</th><th>Spec Coding</th><th>推荐</th></tr></thead><tbody><tr><td>个人 Todo App 原型</td><td>✅ 极快</td><td>⚠️ 有点大材小用</td><td>Vibe</td></tr><tr><td>SaaS MVP</td><td>✅ 快速验证想法</td><td>⚠️ PRD 耗时</td><td>Vibe (原型)</td></tr><tr><td>企业 ERP 系统</td><td>❌ 代码不可控</td><td>✅ 生产就绪</td><td>Spec</td></tr><tr><td>团队协作项目</td><td>❌ 无规格文档</td><td>✅ PRD 对齐</td><td>Spec</td></tr><tr><td>创意 UI 探索</td><td>✅ 探索空间大</td><td>⚠️ 过于结构化</td><td>Vibe</td></tr><tr><td>代码库重构</td><td>❌ 缺乏规划</td><td>✅ 按规格执行</td><td>Spec</td></tr><tr><td>学习新技术</td><td>✅ 快速试错</td><td>⚠️ 过于正式</td><td>Vibe</td></tr><tr><td>安全敏感系统</td><td>❌ 无法审计</td><td>✅ 可审计</td><td>Spec</td></tr></tbody></table><hr><h2 id="_5-参考资料" tabindex="-1">5. 参考资料 <a class="header-anchor" href="#_5-参考资料" aria-label="Permalink to &quot;5. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.augmentcode.com/guides/vibe-coding-vs-spec-driven-development" target="_blank" rel="noreferrer">Vibe Coding vs Spec-Driven Development (Augment Code)</a></li><li><a href="https://prommer.net/en/tech/guides/vibe-coding-enterprise/" target="_blank" rel="noreferrer">Vibe Coding vs Spec-Driven Development: Enterprise Guide (prommer.net)</a></li><li><a href="https://intent-driven.dev/knowledge/vibe-coding-vs-sdd/" target="_blank" rel="noreferrer">Vibe vs Spec Coding (intent-driven.dev)</a></li><li><a href="https://zencoder.ai/blog/spec-driven-development-vs-vibe-coding" target="_blank" rel="noreferrer">Spec-Driven Development vs. Vibe Coding (zencoder.ai)</a></li><li><a href="https://geraldtui.com/posts/spec-coding-workflow/" target="_blank" rel="noreferrer">Vibe vs Spec Coding: Why Structure Matters (geraldtui.com)</a></li><li><a href="https://www.bradjolicoeur.com/article/ai-software-engineering-vibe-spec-prompting" target="_blank" rel="noreferrer">Master AI in Software Engineering: Vibe vs. Spec Coding (bradjolicoeur.com)</a></li><li><a href="https://docs.bswen.com/blog/2026-03-25-vibe-spec-harness-comparison/" target="_blank" rel="noreferrer">Vibe Coding vs Spec Coding vs Harness Engineer (bswen.com)</a></li></ul>`,26)])])}const g=e(i,[["render",n]]);export{b as __pageData,g as default};
